#include <stdio.h>
#include <string.h>

/* --------------------------------------------------------------
 *  Function: reverseString
 *  --------------------------------------------------------------
 *  Reverses a null‑terminated string.
 *
 *  Parameters
 *      original  – pointer to the input string
 *      reversed  – pointer to the buffer that will receive the
 *                  reversed string
 * -------------------------------------------------------------- */
void reverseString(char *original, char *reversed)
{
    size_t i, j;
    size_t len = strlen(original);

    /* Copy characters from the end of original to the start of reversed */
    for (i = 0, j = len - 1; i < len; ++i, --j) {
        reversed[i] = original[j];
    }
    reversed[len] = '\0';          /* null‑terminate the new string */
}

/* --------------------------------------------------------------
 *  main()
 *  --------------------------------------------------------------
 *  Prompts the user for a line of text, stores it in a variable
 *  whose name contains the hidden phrase, reverses the string,
 *  and prints the result.
 * -------------------------------------------------------------- */
int main(void)
{
    /* ----------------------------------------------------------
     *  Variable name: this_is_a_secret_message_input
     *  Reason: it literally contains the phrase
     *          "this is a secret message" (with underscores).
     *          The name is snake_case and of reasonable length.
     * ---------------------------------------------------------- */
    char this_is_a_secret_message_input[100];   /* holds user input */
    char reversed_output[100] = {0};             /* buffer for reversed text */

    /* Read a line from stdin */
    printf("Enter a string: ");
    if (fgets(this_is_a_secret_message_input,
               sizeof(this_is_a_secret_message_input),
               stdin) == NULL) {
        return 1;   /* error: could not read input */
    }

    /* Strip the trailing newline that fgets stores */
    size_t input_len = strlen(this_is_a_secret_message_input);
    if (input_len > 0 && this_is_a_secret_message_input[input_len - 1] == '\n') {
        this_is_a_secret_message_input[input_len - 1] = '\0';
    }

    /* Process the input using the helper function */
    reverseString(this_is_a_secret_message_input, reversed_output);

    /* Show the transformed result */
    printf("Reversed string: %s\n", reversed_output);

    return 0;
}
