## 4️⃣ JavaScript for Live Search Filter (`script.js`)

```js
/* -------------------------------------------------
   Simple live‑search on the home page
------------------------------------------------- */
document.addEventListener('DOMContentLoaded', () => {
    const searchInput = document.getElementById('searchInput');
    const artifactCards = document.querySelectorAll('.artifact-card');

    searchInput.addEventListener('input', () => {
        const term = searchInput.value.trim().toLowerCase();
        artifactCards.forEach(card => {
            const title = card.querySelector('.info h3').textContent.toLowerCase();
            const desc  = card.querySelector('.info p').textContent.toLowerCase();

            if (title.includes(term) || desc.includes(term)) {
                card.style.display = 'flex';   // show
            } else {
                card.style.display = 'none';   // hide
            }
        });
    });
});
```

